// Coleta, normaliza e monta o prompt. Node "Consolidar dados" do n8n.
// Toda fonte que falha entra em `falhas` e é impressa no rodapé do e-mail.

const fmtBR = (n, dec) => Number(n).toLocaleString('pt-BR', { minimumFractionDigits: dec, maximumFractionDigits: dec });
const indicadores = [];
const macro = [];
const paraTexto = [];
const falhas = [];

// n8n entrega array JSON como itens separados; isto tolera os dois formatos
const itens = (node) => {
  const arr = $(node).all().map(i => i.json);
  if (arr.length === 1 && Array.isArray(arr[0])) return arr[0];
  return arr;
};

// ---------- Ibovespa (brapi) ----------
try {
  const ibov = $('Ibovespa (brapi)').first().json.results[0];
  if (!ibov || ibov.regularMarketPrice == null) throw new Error('sem cotação');
  let closes = [];
  try { closes = (ibov.historicalDataPrice || []).map(h => h.close).filter(c => c != null).slice(-6); } catch (e) {}
  if (!closes.length) falhas.push('série 5d do Ibovespa');
  indicadores.push({
    nome: 'Ibovespa',
    valor: fmtBR(ibov.regularMarketPrice, 0) + ' pts',
    delta: ibov.regularMarketChangePercent ?? null,
    closes
  });
  paraTexto.push('Ibovespa: ' + fmtBR(ibov.regularMarketPrice, 0) + ' pts (' + (ibov.regularMarketChangePercent ?? 0).toFixed(2) + '% no dia)');
} catch (e) { falhas.push('Ibovespa (brapi)'); }

// ---------- Câmbio (AwesomeAPI) ----------
const fxHist = (node, rotulo) => {
  try {
    const lista = itens(node).map(x => Number(x.bid)).filter(v => isFinite(v));
    if (lista.length < 3) throw new Error('série curta');
    return lista.reverse();
  } catch (e) { falhas.push('série 5d do ' + rotulo); return []; }
};
try {
  const fx = $('Câmbio (AwesomeAPI)').first().json;
  indicadores.push({ nome: 'Dólar', valor: 'R$ ' + fmtBR(fx.USDBRL.bid, 2), delta: Number(fx.USDBRL.pctChange), closes: fxHist('Histórico Dólar (AwesomeAPI)', 'dólar') });
  indicadores.push({ nome: 'Euro', valor: 'R$ ' + fmtBR(fx.EURBRL.bid, 2), delta: Number(fx.EURBRL.pctChange), closes: fxHist('Histórico Euro (AwesomeAPI)', 'euro') });
  paraTexto.push('Dólar: R$ ' + fmtBR(fx.USDBRL.bid, 2) + ' (' + fx.USDBRL.pctChange + '% no dia)');
  paraTexto.push('Euro: R$ ' + fmtBR(fx.EURBRL.bid, 2) + ' (' + fx.EURBRL.pctChange + '% no dia)');
} catch (e) { falhas.push('Câmbio (AwesomeAPI)'); }

// ---------- Índices e commodities: Yahoo, com Stooq de reserva ----------
const doYahoo = (node) => {
  const r = $(node).first().json.chart.result[0];
  const m = r.meta;
  if (m.regularMarketPrice == null) throw new Error('sem preço');
  const ant = m.chartPreviousClose ?? m.previousClose;
  let closes = [];
  try { closes = r.indicators.quote[0].close.filter(c => c != null).slice(-6); } catch (e) {}
  return { preco: m.regularMarketPrice, delta: ant ? ((m.regularMarketPrice - ant) / ant) * 100 : null, closes };
};
const doStooq = (node) => {
  const first = $(node).first().json;
  const txt = typeof first === 'string' ? first : (first.data || first.body || JSON.stringify(first));
  const closes = String(txt).trim().split('\n').slice(1).map(l => Number(l.split(',')[4])).filter(v => isFinite(v));
  if (closes.length < 2) throw new Error('csv vazio');
  const ult = closes[closes.length - 1], ant = closes[closes.length - 2];
  return { preco: ult, delta: ((ult - ant) / ant) * 100, closes: closes.slice(-6) };
};
const ativo = (nome, nodeYahoo, nodeStooq, prefixo, dec) => {
  let r = null;
  try { r = doYahoo(nodeYahoo); } catch (e) {}
  if (!r) { try { r = doStooq(nodeStooq); falhas.push(nome + ' (via Stooq)'); } catch (e) {} }
  if (!r) { falhas.push(nome); return; }
  indicadores.push({ nome, valor: prefixo + fmtBR(r.preco, dec), delta: r.delta, closes: r.closes });
  paraTexto.push(nome + ': ' + prefixo + fmtBR(r.preco, dec) + ' (' + (r.delta ?? 0).toFixed(2) + '% no dia)');
};
ativo('S&P 500', 'S&P 500 (Yahoo)', 'S&P 500 (Stooq)', '', 2);
ativo('Nasdaq', 'Nasdaq (Yahoo)', 'Nasdaq (Stooq)', '', 2);
ativo('Petróleo WTI', 'Petróleo WTI (Yahoo)', 'Petróleo WTI (Stooq)', 'US$ ', 2);
ativo('Ouro', 'Ouro (Yahoo)', 'Ouro (Stooq)', 'US$ ', 2);

// ---------- Macro (séries SGS do Banco Central) ----------
const serieBCB = (node) => {
  const lista = itens(node);
  const ultimo = lista[lista.length - 1];
  if (!ultimo || ultimo.valor == null) throw new Error('sem série');
  return ultimo;
};
try {
  const s = serieBCB('Selic (BCB)');
  macro.push({ nome: 'Selic (meta)', valor: String(s.valor).replace('.', ',') + '% a.a.', nota: 'vigente' });
  paraTexto.push('Selic meta: ' + s.valor + '% a.a.');
} catch (e) { falhas.push('Selic (BCB)'); }
try {
  const i = serieBCB('IPCA (BCB)');
  macro.push({ nome: 'IPCA', valor: String(i.valor).replace('.', ',') + '%', nota: 'último mês fechado' });
  paraTexto.push('IPCA do último mês fechado: ' + i.valor + '%');
} catch (e) { falhas.push('IPCA (BCB)'); }

// ---------- Notícias ----------
let noticiasBR = '', noticiasGlobal = '';
try { noticiasBR = $('Notícias BR (InfoMoney)').all().slice(0, 12).map(i => '- ' + i.json.title).join('\n'); } catch (e) { falhas.push('InfoMoney'); }
try { noticiasGlobal = $('Notícias Global (CNBC)').all().slice(0, 12).map(i => '- ' + i.json.title).join('\n'); } catch (e) { falhas.push('CNBC'); }

// ---------- Contexto temporal (o texto muda se rodar de manhã ou depois do pregão) ----------
const agora = new Date();
const fmtData = (o) => agora.toLocaleDateString('pt-BR', Object.assign({ timeZone: 'America/Sao_Paulo' }, o));
const dataFmt = fmtData({ weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
const horaFmt = agora.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
const hora = Number(agora.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo', hour: '2-digit', hour12: false }));

let recorte, instrucaoTempo;
if (hora < 10) {
  recorte = 'antes da abertura';
  instrucaoTempo = 'O briefing sai antes da abertura do pregão brasileiro. Os números de ações locais referem-se ao fechamento anterior; fale no passado sobre ontem e no futuro sobre o que o dia reserva.';
} else if (hora < 18) {
  recorte = 'dados parciais do pregão';
  instrucaoTempo = 'O pregão está em andamento. Deixe claro que os números brasileiros são parciais, use "opera", "avança", "recua" no presente.';
} else {
  recorte = 'após o fechamento';
  instrucaoTempo = 'O pregão já fechou. Fale no passado: "fechou", "encerrou o dia".';
}

const prompt = 'Você é o estrategista que assina o briefing de mercado de ' + dataFmt + ', publicado ' + recorte + ' (' + horaFmt + ' de Brasília), para um investidor brasileiro.\n\n' +
  'ESTILO: escrita fluida de newsletter de research, no padrão das casas de análise. Frases encadeadas por causa e efeito, vocabulário preciso, nada de burocratês nem sensacionalismo. Proibido: emoji, exclamação, clichê de mercado ("montanha-russa", "olho do furacão", "cautela impera"). ' + instrucaoTempo + '\n\n' +
  'DADOS DE MERCADO (use somente estes números; não invente nem arredonde para outro valor):\n' + paraTexto.join('\n') + '\n\n' +
  'MANCHETES BRASIL (InfoMoney):\n' + (noticiasBR || 'indisponível') + '\n\n' +
  'MANCHETES GLOBAIS (CNBC):\n' + (noticiasGlobal || 'indisponível') + '\n\n' +
  'Responda SOMENTE com JSON válido, sem markdown, neste formato:\n' +
  '{\n' +
  '  "manchete": "título do dia, máx 95 caracteres, com o fato principal e, se couber, um número",\n' +
  '  "lead": "1 parágrafo de 2 a 3 frases que resume a edição inteira; quem ler só isso entende o dia",\n' +
  '  "visao_geral": "2 a 3 frases ligando o cenário externo ao doméstico",\n' +
  '  "brasil": "3 a 5 frases sobre Ibovespa, câmbio e o que explica os movimentos; traga Selic ou IPCA quando ajudar a explicar",\n' +
  '  "eua_mundo": "3 a 5 frases sobre índices americanos, commodities e o pano de fundo macro",\n' +
  '  "implicacao": "2 a 3 frases de leitura estratégica: o que esse conjunto sugere, qual tese ganha ou perde força. Comece com a avaliação, não com resumo",\n' +
  '  "vetor": "uma frase curta: o indicador, evento ou preço específico que deve ser acompanhado para confirmar ou derrubar a leitura acima",\n' +
  '  "noticias": [ { "titulo": "manchete reescrita de forma clara", "contexto": "1 a 2 frases de por que importa para quem investe" } ]\n' +
  '}\n' +
  'Em "noticias", escolha as 5 histórias mais relevantes do dia, misturando Brasil e mundo, priorizando impacto de mercado e descartando fait divers. Texto puro nos valores, sem HTML e sem aspas duplas internas. Comente apenas indicadores que aparecem nos dados acima.';

return [{ json: { prompt, indicadores, macro, dataFmt, horaFmt, recorte, falhas, edicao: 'Briefing diário' } }];

// Monta o HTML do briefing. Padrão visual Malibu + estrutura editorial de research institucional.
// Regra: este arquivo NUNCA inventa número. Recebe `base` (dados reais) e `ia` (texto do modelo).

function montarEmail(base, ia) {
  var NAVY = '#040F2B', BANDA = '#0A1E4A', CYAN = '#00BFFF', CYAN_DK = '#0099CC';
  var TXT = '#1A2442', SEC = '#5A6880', MUTED = '#8B9EC7', LINHA = '#E8ECF5', OFF = '#F0F4FF';
  var UP = '#4ADE80', DOWN = '#F87171', FLAT = '#B9C6E4';

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  // delta: trata o quase-zero (evita o "-0,00%") e devolve sinal, cor e rótulo
  function lerDelta(d) {
    if (d === null || d === undefined || !isFinite(d)) return null;
    var zero = Math.abs(d) < 0.005;
    return {
      zero: zero,
      up: !zero && d > 0,
      down: !zero && d < 0,
      cor: zero ? FLAT : (d > 0 ? UP : DOWN),
      texto: zero ? '0,00%' : (d > 0 ? '+' : '−') + Math.abs(d).toFixed(2).replace('.', ',') + '%',
      seta: zero ? '&#9644;' : (d > 0 ? '&#9650;' : '&#9660;')
    };
  }

  // sparkline como imagem (e-mail não executa JS). Cor segue o MESMO sinal do delta do dia.
  function spark(closes, cor) {
    if (!closes || closes.length < 3) return '';
    var dados = closes.filter(function (c) { return c !== null && isFinite(c); })
      .map(function (c) { return Math.round(c * 10000) / 10000; });
    if (dados.length < 3) return '';
    var cfg = "{type:'sparkline',data:{datasets:[{data:[" + dados.join(',') +
      "],borderColor:'" + cor + "',borderWidth:2.5,fill:false,pointRadius:0}]}}";
    return 'https://quickchart.io/chart?w=92&h=30&c=' + encodeURIComponent(cfg);
  }

  // ---------------- faixa de indicadores ----------------
  var linhas = (base.indicadores || []).map(function (i) {
    var dl = lerDelta(i.delta);
    var cor = dl ? dl.cor : FLAT;
    var chip = '<span style="font-family:\'Courier New\',monospace;font-size:13px;color:' + MUTED + ';">&mdash;</span>';
    if (dl) {
      var fundo = dl.zero ? 'rgba(139,158,199,0.15)' : (dl.up ? 'rgba(34,197,94,0.15)' : 'rgba(239,68,68,0.15)');
      chip = '<span style="display:inline-block;padding:4px 12px;border-radius:999px;background:' + fundo +
        ';color:' + cor + ';font-family:\'Courier New\',monospace;font-size:13px;font-weight:700;white-space:nowrap;">' +
        dl.seta + ' ' + dl.texto + '</span>';
    }
    var url = spark(i.closes, cor);
    var grafico = url
      ? '<img src="' + url + '" width="92" height="30" alt="" style="display:block;border:0;" />'
      : '<span style="font-family:Arial,sans-serif;font-size:10px;color:#2E4572;">s/ s&eacute;rie</span>';

    return '<tr>' +
      '<td style="padding:11px 0;font-family:Arial,Helvetica,sans-serif;font-size:13px;letter-spacing:1.2px;color:#B9C6E4;text-transform:uppercase;font-weight:700;">' + esc(i.nome) + '</td>' +
      '<td align="center" width="104" style="padding:11px 0;">' + grafico + '</td>' +
      '<td align="right" style="padding:11px 0;font-family:\'Courier New\',monospace;font-size:18px;color:#FFFFFF;font-weight:700;white-space:nowrap;">' + esc(i.valor) + '</td>' +
      '<td align="right" width="108" style="padding:11px 0 11px 14px;">' + chip + '</td>' +
      '</tr>';
  }).join('<tr><td colspan="4" style="border-bottom:1px solid rgba(139,158,199,0.15);font-size:0;line-height:0;">&nbsp;</td></tr>');

  // ---------------- blocos reutilizáveis ----------------
  function kicker(num, titulo) {
    return '<table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"><tr>' +
      '<td width="3" style="background:' + CYAN + ';font-size:0;line-height:0;">&nbsp;</td>' +
      '<td style="padding-left:10px;font-family:\'Courier New\',monospace;font-size:11px;letter-spacing:1.6px;color:' + CYAN_DK + ';text-transform:uppercase;font-weight:700;">' +
      (num ? num + ' // ' : '') + titulo + '</td></tr></table>';
  }

  function secao(num, titulo, texto) {
    if (!texto) return '';
    return '<tr><td style="padding:28px 36px 0;">' + kicker(num, titulo) +
      '<p style="margin:0;font-family:Georgia,\'Times New Roman\',serif;font-size:15px;line-height:1.68;color:#33415C;text-align:justify;">' + esc(texto) + '</p>' +
      '</td></tr>';
  }

  // ---------------- notícias ----------------
  var noticias = (ia.noticias || []).slice(0, 5).map(function (n, idx) {
    return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:' + (idx === 0 ? '0' : '20px') + ';"><tr>' +
      '<td width="44" valign="top" style="font-family:\'Courier New\',monospace;font-size:20px;font-weight:700;color:' + CYAN + ';">' + ('0' + (idx + 1)) + '</td>' +
      '<td valign="top">' +
      '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:700;color:' + TXT + ';line-height:1.45;">' + esc(n.titulo) + '</div>' +
      '<div style="font-family:Georgia,serif;font-size:13px;color:' + SEC + ';line-height:1.6;margin-top:5px;">' + esc(n.contexto) + '</div>' +
      '</td></tr></table>';
  }).join('');

  var blocoNoticias = noticias
    ? '<tr><td style="padding:28px 36px 0;">' + kicker('03', 'O que importa hoje') + noticias + '</td></tr>'
    : '';

  // ---------------- implicação estratégica ----------------
  var blocoImplicacao = ia.implicacao
    ? '<tr><td style="padding:28px 36px 0;">' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + OFF + ';border-radius:10px;"><tr>' +
      '<td width="4" style="background:' + CYAN + ';font-size:0;line-height:0;border-radius:10px 0 0 10px;">&nbsp;</td>' +
      '<td style="padding:18px 22px;">' +
      '<div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:1.6px;color:' + CYAN_DK + ';text-transform:uppercase;font-weight:800;margin-bottom:8px;">Implica&ccedil;&atilde;o estrat&eacute;gica</div>' +
      '<p style="margin:0;font-family:Georgia,serif;font-size:14px;line-height:1.65;color:' + TXT + ';font-style:italic;">' + esc(ia.implicacao) + '</p>' +
      (ia.vetor ? '<p style="margin:10px 0 0;font-family:Arial,Helvetica,sans-serif;font-size:12.5px;line-height:1.55;color:' + SEC + ';"><strong style="color:' + TXT + ';">Vetor a monitorar:</strong> ' + esc(ia.vetor) + '</p>' : '') +
      '<p style="margin:10px 0 0;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:' + MUTED + ';">Leitura de cen&aacute;rio, n&atilde;o recomenda&ccedil;&atilde;o de investimento.</p>' +
      '</td></tr></table></td></tr>'
    : '';

  // ---------------- macro ----------------
  var cards = (base.macro || []);
  var macroCols = cards.map(function (m) {
    return '<td align="center" width="' + Math.floor(100 / cards.length) + '%" style="padding:14px 10px;background:' + OFF + ';border-radius:10px;">' +
      '<div style="font-family:Arial,Helvetica,sans-serif;font-size:10px;letter-spacing:1.2px;color:' + MUTED + ';text-transform:uppercase;font-weight:700;">' + esc(m.nome) + '</div>' +
      '<div style="font-family:\'Courier New\',monospace;font-size:17px;font-weight:700;color:' + TXT + ';margin-top:5px;">' + esc(m.valor) + '</div>' +
      (m.nota ? '<div style="font-family:Arial,Helvetica,sans-serif;font-size:10px;color:' + MUTED + ';margin-top:3px;">' + esc(m.nota) + '</div>' : '') +
      '</td>';
  }).join('<td width="10"></td>');

  var blocoMacro = cards.length
    ? '<tr><td style="padding:28px 36px 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' + macroCols + '</tr></table></td></tr>'
    : '';

  // ---------------- documento ----------------
  return '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>' +
    '<body style="margin:0;padding:0;background:' + OFF + ';">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + OFF + ';"><tr><td align="center" style="padding:28px 12px;">' +
    '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;">' +

    // masthead
    '<tr><td style="background:' + NAVY + ';border-radius:14px 14px 0 0;padding:30px 36px 26px;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' +
    '<td style="font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:800;letter-spacing:-0.2px;color:#FFFFFF;">INTELIG&Ecirc;NCIA DE MERCADO<span style="color:' + CYAN + ';">.</span></td>' +
    '<td align="right" style="font-family:\'Courier New\',monospace;font-size:10px;letter-spacing:1.4px;color:' + MUTED + ';text-transform:uppercase;">' + esc(base.edicao || 'Briefing diário') + '</td>' +
    '</tr></table>' +
    '<div style="font-family:\'Courier New\',monospace;font-size:10.5px;letter-spacing:1.1px;color:' + MUTED + ';text-transform:uppercase;margin-top:20px;">' + esc(base.dataFmt) + ' &middot; ' + esc(base.recorte || '') + '</div>' +
    '<div style="font-family:Georgia,\'Times New Roman\',serif;font-size:25px;line-height:1.28;color:#FFFFFF;margin-top:10px;font-weight:700;">' + esc(ia.manchete || 'Resumo do mercado') + '</div>' +
    (ia.lead ? '<p style="margin:14px 0 0;font-family:Georgia,serif;font-size:13.5px;line-height:1.6;color:#B9C6E4;font-style:italic;">' + esc(ia.lead) + '</p>' : '') +
    '</td></tr>' +

    // faixa de mercados
    '<tr><td style="background:' + BANDA + ';padding:24px 36px 20px;">' +
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:1.8px;color:' + CYAN + ';text-transform:uppercase;font-weight:800;margin-bottom:12px;">Mercados agora &middot; tend&ecirc;ncia 5 dias</div>' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">' + linhas + '</table>' +
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:10.5px;line-height:1.5;color:#5A6880;margin-top:14px;">Varia&ccedil;&atilde;o no dia. Minigr&aacute;fico: fechamentos dos &uacute;ltimos 5 preg&otilde;es. Captura &agrave;s ' + esc(base.horaFmt) + '.</div>' +
    '</td></tr>' +

    // corpo
    '<tr><td style="background:#FFFFFF;padding:2px 0 0;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">' +
    secao('', 'Visão geral', ia.visao_geral) +
    blocoMacro +
    secao('01', 'Brasil', ia.brasil) +
    secao('02', 'EUA e mundo', ia.eua_mundo) +
    blocoImplicacao +
    blocoNoticias +

    // assinatura
    '<tr><td style="padding:30px 36px 0;">' +
    '<div style="border-top:2px solid ' + LINHA + ';padding-top:16px;">' +
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:13px;font-weight:700;color:' + TXT + ';">Victor Borges</div>' +
    '<div style="font-family:\'Courier New\',monospace;font-size:11px;letter-spacing:1px;color:' + MUTED + ';text-transform:uppercase;margin-top:3px;">Intelig&ecirc;ncia de Mercado &middot; briefing automatizado</div>' +
    '</div></td></tr>' +
    '<tr><td style="padding:26px 36px;"></td></tr>' +
    '</table></td></tr>' +

    // rodapé
    '<tr><td style="background:' + NAVY + ';border-radius:0 0 14px 14px;padding:22px 36px;">' +
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;color:' + MUTED + ';line-height:1.65;">Gerado automaticamente &agrave;s ' + esc(base.horaFmt) + ' (hor&aacute;rio de Bras&iacute;lia). Cota&ccedil;&otilde;es: B3 via brapi, c&acirc;mbio via AwesomeAPI, &iacute;ndices e commodities via Yahoo Finance com fallback Stooq. Macro: s&eacute;ries SGS do Banco Central. Not&iacute;cias: InfoMoney e CNBC. Texto redigido por modelo de linguagem a partir desses dados; os n&uacute;meros do painel v&ecirc;m direto das fontes, sem interm&eacute;dio do modelo.</div>' +
    ((base.falhas && base.falhas.length)
      ? '<div style="font-family:\'Courier New\',monospace;font-size:10.5px;color:' + DOWN + ';line-height:1.6;margin-top:8px;">Fontes indispon&iacute;veis nesta execu&ccedil;&atilde;o: ' + esc(base.falhas.join(', ')) + '</div>'
      : '') +
